create table if not exists public.publisher_submissions ( id uuid primary key default gen_random_uuid(), full_name text not null check (length(btrim(full_name)) between 1 and 120), email text not null check (position('@' in email) > 1 and length(email) <= 320), domain text not null check (length(btrim(domain)) between 3 and 253), placement_type text check (placement_type is null or length(placement_type) <= 40), price_minor integer check (price_minor is null or price_minor > 0), currency text check (currency is null or currency in ('GBP', 'USD', 'EUR')), constraint publisher_submissions_price_has_currency check ((price_minor is null) = (currency is null)), message text check (message is null or length(btrim(message)) between 1 and 4000), source text not null default 'list-your-site' check (length(source) <= 40), matched_website_id uuid references public.websites (id) on delete set null, status text not null default 'new' check (status in ('new', 'in-progress', 'listed', 'declined', 'spam')), handled_by text, handled_at timestamptz, notes text check (notes is null or length(notes) <= 4000), created_at timestamptz not null default timezone('utc', now()) );
comment on table public.publisher_submissions is 'Publishers offering a site through /list-your-site. Internal: a named person''s address and what they want paid. No customer-facing policy.';
comment on column public.publisher_submissions.price_minor is 'Minor units, and never stored without a currency - a number whose currency was guessed becomes a cost we never agreed.';
