create index if not exists publisher_submissions_domain_idx on public.publisher_submissions (domain);
alter table public.publisher_submissions enable row level security;
do $$ begin create policy "Admins manage publisher submissions" on public.publisher_submissions for all using (public.is_admin()) with check (public.is_admin()); exception when duplicate_object then null; end; $$;
